values(19,'speaking','Full Speaking · Day 19','published',$json${"version":"speaking-day-19-v1","part1":{"topic":"TOPIC 20. CLOTHES","questions":[{"key":"p1_q1","text":"Do you usually wear T-shirts?"},{"key":"p1_q2","text":"Do you like wearing T-shirts?"},{"key":"p1_q3","text":"Do you like T-shirts with pictures and prints?"},{"key":"p1_q4","text":"What colour clothes do you like to wear?"},{"key":"p1_q5","text":"What are the differences between men and women's preference in colour?"},{"key":"p1_q6","text":"What kind of clothes do you like to wear?"},{"key":"p1_q7","text":"What kind of clothes do you never wear?"},{"key":"p1_q8","text":"Do you wear the same style of clothes on weekdays and weekends?"}]},"part2":{"key":"p2_main","topic":"TOPIC 19. SPECIAL DAY OUT THAT DIDN'T COST A LOT","prompt":"Describe a special day out that didn't cost a lot.","bullets":["what you did","when it was","who you were with","why it was special"],"preparation_seconds":60,"max_answer_seconds":120},"part3":{"topic":"TOPIC 19. LEISURE TIME","questions":[{"key":"p3_q1","text":"What leisure activities do old and young people prefer?"},{"key":"p3_q2","text":"How do people spend their leisure time in your country?"},{"key":"p3_q3","text":"How does technology affect the way people spend leisure time?"},{"key":"p3_q4","text":"Is leisure time important for everyone?"},{"key":"p3_q5","text":"Do you think only old people have time for leisure?"}]}}$json$::jsonb,now(),now())
